PRAGMA foreign_keys = ON;
CREATE TABLE customers(id INTEGER PRIMARY KEY,name TEXT NOT NULL,email TEXT,preferred_address_id INTEGER REFERENCES addresses(id));
CREATE TABLE addresses(id INTEGER PRIMARY KEY,customer_id INTEGER REFERENCES customers(id),city TEXT,street TEXT);
CREATE TABLE products(id INTEGER PRIMARY KEY,name TEXT NOT NULL,price TEXT NOT NULL,attributes TEXT);
CREATE TABLE orders(id INTEGER PRIMARY KEY,customer_id INTEGER NOT NULL REFERENCES customers(id),status TEXT NOT NULL DEFAULT 'pending',total TEXT,metadata TEXT,secret_token TEXT,placed_at TEXT);
CREATE TABLE order_items(order_id INTEGER REFERENCES orders(id),line_number INTEGER,product_id INTEGER REFERENCES products(id),quantity INTEGER,PRIMARY KEY(order_id,line_number));
CREATE TABLE payments(id INTEGER PRIMARY KEY,order_id INTEGER REFERENCES orders(id),status TEXT,amount TEXT,receipt BLOB);
CREATE TABLE no_identity(note TEXT);
CREATE TABLE composite_parent(tenant TEXT NOT NULL,code TEXT NOT NULL,label TEXT,PRIMARY KEY(tenant,code));
CREATE TABLE composite_child(id INTEGER PRIMARY KEY,tenant TEXT,code TEXT,FOREIGN KEY(tenant,code) REFERENCES composite_parent(tenant,code));
CREATE VIEW pending_orders AS SELECT id,customer_id,status,total FROM orders WHERE status='pending';
CREATE INDEX orders_customer_idx ON orders(customer_id);
